"""matplotlib.streamplot — re-export of the pyplot streamplot."""

from matplotlib.pyplot import streamplot  # noqa: F401

__all__ = ['streamplot']


# ─── Added: missing public names from upstream streamplot.py ────────


class TerminateTrajectory(Exception):
    """Internal sentinel used by the streamline tracer to stop following
    a path (e.g. when it leaves the grid). Exposed for isinstance
    checks in user-supplied integrators."""
    pass


class OutOfBounds(IndexError):
    """Raised when an integrator step lands outside the grid."""
    pass


class InvalidIndexError(IndexError):
    """Raised by :class:`StreamMask` when an attempt is made to mark a
    cell with an out-of-range index."""
    pass


class StreamplotSet:
    """Container returned by :func:`streamplot` — holds the polylines
    and arrow patches that make up the streamline visualisation."""

    def __init__(self, lines=None, arrows=None):
        self.lines = lines or []
        self.arrows = arrows or []


class Grid:
    """Cartesian sampling grid used by the streamline tracer. Holds the
    x/y axis vectors and exposes a few helpers for mapping (x, y) to
    grid indices."""

    def __init__(self, x, y):
        import numpy as _np
        self.x = _np.asarray(x)
        self.y = _np.asarray(y)
        self.nx = len(self.x)
        self.ny = len(self.y)
        self.dx = (self.x[-1] - self.x[0]) / max(1, self.nx - 1)
        self.dy = (self.y[-1] - self.y[0]) / max(1, self.ny - 1)
        self.shape = (self.ny, self.nx)
        self.width = self.x[-1] - self.x[0]
        self.height = self.y[-1] - self.y[0]

    def within_grid(self, xi, yi):
        return (0 <= xi < self.nx) and (0 <= yi < self.ny)


class StreamMask:
    """Bookkeeping mask used by streamplot to avoid drawing overlapping
    streamlines through the same cell. Each cell can be touched once;
    subsequent attempts raise :class:`InvalidIndexError`."""

    def __init__(self, density):
        # ``density`` may be a scalar or (nx, ny) pair.
        if hasattr(density, '__len__'):
            ny, nx = int(density[1]), int(density[0])
        else:
            ny = nx = int(30 * density)
        import numpy as _np
        self._mask = _np.zeros((ny, nx), dtype=bool)
        self.shape = (ny, nx)

    def __getitem__(self, idx):
        return self._mask[idx]

    def __setitem__(self, idx, value):
        try:
            self._mask[idx] = value
        except IndexError as e:
            raise InvalidIndexError(str(e))


class DomainMap:
    """Translate between data coordinates and the streamline mask /
    grid index spaces. Holds the source ``Grid`` and ``StreamMask``."""

    def __init__(self, grid, mask):
        self.grid = grid
        self.mask = mask

    def grid2mask(self, xi, yi):
        mny, mnx = self.mask.shape
        return int(yi * mny / self.grid.ny), int(xi * mnx / self.grid.nx)

    def mask2grid(self, mxi, myi):
        return int(mxi * self.grid.nx / self.mask.shape[1]), \
               int(myi * self.grid.ny / self.mask.shape[0])

    def data2grid(self, xd, yd):
        gx = (xd - self.grid.x[0]) / self.grid.dx
        gy = (yd - self.grid.y[0]) / self.grid.dy
        return gx, gy

    def grid2data(self, gx, gy):
        return self.grid.x[0] + gx * self.grid.dx, \
               self.grid.y[0] + gy * self.grid.dy


def interpgrid(a, xi, yi):
    """Bilinear interpolation of array ``a`` at fractional indices
    ``(xi, yi)``. ``a`` is a 2-D array indexed as ``a[yi, xi]``.
    Used by the streamline tracer to sample the vector field at sub-
    cell resolution.
    """
    import numpy as _np
    a = _np.asarray(a)
    Ny, Nx = a.shape
    # Clamp to inside the grid.
    xi = max(0.0, min(float(xi), Nx - 1 - 1e-9))
    yi = max(0.0, min(float(yi), Ny - 1 - 1e-9))
    x0, y0 = int(xi), int(yi)
    fx, fy = xi - x0, yi - y0
    # Bilinear weights.
    return (a[y0,     x0]     * (1 - fx) * (1 - fy)
          + a[y0,     x0 + 1] *      fx  * (1 - fy)
          + a[y0 + 1, x0]     * (1 - fx) *      fy
          + a[y0 + 1, x0 + 1] *      fx  *      fy)


# ─── Added: DomainMap trajectory helpers ────────────────────────────


def _dm_reset_start_point(self, xg, yg):
    """Start a fresh trajectory at grid coords ``(xg, yg)``."""
    self._start = (xg, yg)
    self._traj = [(xg, yg)]
    self._mask_modifications = []  # so undo() can revert each cell flip

def _dm_start_trajectory(self, xg, yg):
    """Mark the trajectory's starting cell as visited on the mask."""
    self._traj = [(xg, yg)]
    self._mask_modifications = []
    try:
        mxi, myi = self.grid2mask(xg, yg)
        if not self.mask._mask[mxi, myi]:
            self.mask._mask[mxi, myi] = True
            self._mask_modifications.append((mxi, myi))
    except Exception:
        pass

def _dm_undo_trajectory(self):
    """Revert the cells this trajectory marked on the mask. Called
    when the tracer hits a dead end and needs to give up the partial
    trajectory."""
    for mxi, myi in getattr(self, '_mask_modifications', []):
        try: self.mask._mask[mxi, myi] = False
        except Exception: pass
    self._mask_modifications = []
    self._traj = []

def _dm_update_trajectory(self, xg, yg):
    """Append a new (xg, yg) point to the trajectory; mark its mask
    cell as visited. Raises :class:`InvalidIndexError` (via the mask)
    if the cell is already taken — the tracer treats that as the
    signal to stop."""
    mxi, myi = self.grid2mask(xg, yg)
    try:
        if self.mask._mask[mxi, myi]:
            raise InvalidIndexError('cell already visited')
    except IndexError:
        raise OutOfBounds('trajectory left grid')
    self.mask._mask[mxi, myi] = True
    self._mask_modifications.append((mxi, myi))
    self._traj.append((xg, yg))

DomainMap.reset_start_point = _dm_reset_start_point
DomainMap.start_trajectory  = _dm_start_trajectory
DomainMap.undo_trajectory   = _dm_undo_trajectory
DomainMap.update_trajectory = _dm_update_trajectory


# ── RK4 integrator helper (used by upstream's _gen_streamlines) ────


def _rk4(f, x0, y0, dt, max_steps=1000):
    """Trace a single streamline with the classical 4th-order Runge-
    Kutta scheme. ``f`` is a callable ``f(x, y)`` returning ``(dx, dy)``;
    ``(x0, y0)`` is the seed; ``dt`` the step size.

    Yields ``(x, y)`` points along the path. Halts when ``f`` returns
    a near-zero vector (sink) or after ``max_steps`` iterations.
    """
    import math
    x, y = x0, y0
    for _ in range(max_steps):
        try:
            k1x, k1y = f(x, y)
            k2x, k2y = f(x + 0.5 * dt * k1x, y + 0.5 * dt * k1y)
            k3x, k3y = f(x + 0.5 * dt * k2x, y + 0.5 * dt * k2y)
            k4x, k4y = f(x + dt * k3x, y + dt * k3y)
            dx = dt * (k1x + 2 * k2x + 2 * k3x + k4x) / 6
            dy = dt * (k1y + 2 * k2y + 2 * k3y + k4y) / 6
            if math.hypot(dx, dy) < 1e-9:
                break
            x += dx; y += dy
            yield x, y
        except Exception:
            break


